using System.Numerics;
using System.Reflection;
using ByteEngine.Core.Characters;
using ByteEngine.Core.Gameplay;
using ByteEngine.Core.Scene;
using ByteEngine.Core.Graphics;
using KarlsonDemo.Plugin;
internal static class MiningResearchCheck
{
 static void Check(bool ok,string label){if(!ok)throw new Exception(label);Console.WriteLine("PASS "+label);}
 static void Set(object o,string key,object value)=>o.GetType().GetProperty(key)!.SetValue(o,value);
 public static void Run()
 {
  var scene=new Scene("Research support regressions");var player=scene.CreateGameObject("Player");var hp=player.AddComponent(new HealthComponent());var drill=scene.CreateGameObject("Drill");var rig=drill.AddComponent(new HealthComponent());
  var owner=scene.CreateGameObject("Operation");var op=owner.AddComponent(new MiningOperation3D{PersistProgress=false,TutorialEnabled=false,TargetEnabled=false,PlayerObjectId=player.Id,DrillObjectId=drill.Id,RefineryBatch=3,ExtraBatchPerLevel=2,QueueRefineryBatches=true,RefineryLoadCapacity=50,RefinerySeconds=3,BaseCargoCapacity=10000});op.Initialize();
  Set(op,"RawOre",140);Check(op.BeginRefining()&&op.RefiningAmount==3,"50-ore load preserves small 3-ore processing batches");
  Set(op,"Credits",1000);int cargo=op.CargoCapacity;Check(op.UpgradeCargo()&&op.CargoCapacity==cargo+100&&op.Credits==920,"cargo can expand by 100 without owning R&D");Check(op.UpgradeCargo()&&op.CargoCapacity==cargo+200&&op.Credits==800,"cargo expansion is repeatable with escalating cost");
  var cargoSave=System.Text.Json.JsonSerializer.Deserialize<MiningOperation3D.MiningSave>(System.Text.Json.JsonSerializer.Serialize(new MiningOperation3D.MiningSave{CargoUpgradeLevel=op.CargoUpgradeLevel}))!;Check(cargoSave.CargoUpgradeLevel==2,"cargo expansion level survives serialization");
  for(int i=0;i<17;i++)op.Tick(3.01f);
  Check(op.RawOre==90&&op.RefinedOre==50&&op.RefiningAmount==0&&!op.RefineryQueueActive,"one queued run stops after exactly 50 raw, not the whole cargo hold");
  op.Tick(30);Check(op.RawOre==90,"idle refinery does not silently reload without automation");
  Check(op.BeginRefining(),"another load can be started deliberately");for(int i=0;i<17;i++)op.Tick(3.01f);Check(op.RawOre==40&&op.RefinedOre==100,"second load consumes a separate 50 ore");
  op.RefineryBatch=1000;Check(op.BeginRefining()&&op.RefiningAmount==40,"oversized configured batch obeys load cap and available ore");op.Tick(3.01f);Check(op.RawOre==0&&op.RefinedOre==140,"last partial load conserves ore");
  Set(op,"Credits",10000);int before=op.Credits;Check(!op.Buy(MiningUpgrade.Refinery)&&op.Credits==before,"batch upgrade cannot charge for capacity beyond 50");
  Set(op,"RawOre",80);op.RefineryBatch=3;op.QueueRefineryBatches=false;Check(op.BeginRefining(),"single-batch mode still starts");op.Tick(3.01f);Check(op.RawOre==77&&op.RefiningAmount==0&&op.RefineryLoadRemaining==0,"single-batch mode does not become an automatic queue");
  var enemies=(List<GameObject>)typeof(MiningOperation3D).GetField("_enemies",BindingFlags.NonPublic|BindingFlags.Instance)!.GetValue(op)!;
  var near=scene.CreateGameObject("Nearby spider");near.Transform.WorldPosition=new(1,1.2f,0);var n=near.AddComponent(new HealthComponent());enemies.Add(near);
  var far=scene.CreateGameObject("Distant spider");far.Transform.WorldPosition=new(12,1.2f,0);var f=far.AddComponent(new HealthComponent());enemies.Add(far);
  var behind=scene.CreateGameObject("Sheltered spider");behind.Transform.WorldPosition=new(0,1.2f,-2);var sheltered=behind.AddComponent(new HealthComponent());enemies.Add(behind);
  var wall=scene.CreateGameObject("Solid wall");wall.Transform.WorldPosition=new(0,1.2f,-1);wall.AddComponent(new BoxCollider3D{Size=new(.8f,3,.2f)});
  var drone=scene.CreateGameObject("Security drone");drone.Transform.WorldPosition=new(0,1.7f,0);var support=drone.AddComponent(new MiningSecurityDrone3D{OperationObjectId=owner.Id,BatterySeconds=2,FollowSpeed=.1f,RemoveWhenDepleted=false,ExplosionRadius=3,ExplosionDamage=40,ShotDamage=0});
  support.Tick(.5f);Check(support.BatteryRemaining==2&&!support.Detonated,"drone parks without draining battery between operations");
  Set(op,"Phase",MiningPhase.Drilling);support.Tick(float.NaN);support.Tick(-1);Check(support.BatteryRemaining==2,"invalid clock steps cannot drain or refill battery");
  support.Tick(1);Check(support.BatteryRemaining==1&&support.BatteryLow,"active combat drains finite battery and reports low power");support.Tick(1);
  Check(support.Detonated&&support.BatteryRemaining==0&&n.CurrentHealth==60,"depleted drone explodes and damages a nearby enemy");
  Check(f.CurrentHealth==100&&hp.CurrentHealth==100&&rig.CurrentHealth==op.BaseDrillHealth,"blast excludes distant enemies, player and rig");
  Check(sheltered.CurrentHealth==100,"solid wall protects enemies from drone blast");
  support.Detonate();support.Tick(20);Check(n.CurrentHealth==60&&support.ExplosionVictims==1,"drone detonation is one-shot, not repeated damage");
  var disposable=scene.CreateGameObject("Disposable drone");var d=disposable.AddComponent(new MiningSecurityDrone3D{OperationObjectId=owner.Id,BatterySeconds=.1f,ExplosionDamage=0});d.Tick(.2f);Check(disposable.Scene==null,"spent drone is removed from play");
  foreach(var enemy in enemies.ToArray())scene.DestroyGameObject(enemy);enemies.Clear();var threat=scene.CreateGameObject("Approaching attacker");threat.Transform.WorldPosition=new(10,0,0);threat.AddComponent(new HealthComponent());enemies.Add(threat);
  var autonomous=scene.CreateGameObject("Autonomous defender");autonomous.Transform.WorldPosition=new(2,1.7f,0);var defender=autonomous.AddComponent(new MiningSecurityDrone3D{OperationObjectId=owner.Id,BatterySeconds=60,RemoveWhenDepleted=false});defender.Tick(.25f);
  Check(autonomous.Transform.WorldPosition.X>2&&defender.ShotsFired==1,"drone advances toward an attacker and fires instead of following behind player");Check(defender.BatteryFraction<1&&defender.BatteryFraction>.99f,"combat battery bar fraction decreases continuously");
  var group=new List<GameObject>();for(int i=0;i<4;i++){var e=scene.CreateGameObject("Crowd "+i);e.Transform.WorldPosition=new(15+i,0,24);e.AddComponent(new HealthComponent());enemies.Add(e);group.Add(e);}
  defender.Tick(.5f);Check(group.Any(e=>e.Id==defender.CurrentTargetObjectId)&&defender.TacticalState=="Attack crowd","crowd outranks the lone spider near the player");
  foreach(var e in group)e.GetComponent<HealthComponent>()!.Kill();defender.Tick(.5f);Check(defender.CurrentTargetObjectId==threat.Id&&defender.TacticalState=="Protect player","without crowds, drone attacks enemies threatening player");
  threat.GetComponent<HealthComponent>()!.Kill();Set(op,"Phase",MiningPhase.Preparation);player.Transform.WorldPosition=new(0,0,-80);var start=autonomous.Transform.WorldPosition;defender.Tick(.5f);Check(defender.CurrentTargetObjectId==Guid.Empty&&defender.TacticalState=="Patrol"&&autonomous.Transform.WorldPosition.Z>start.Z,"idle drone patrols forward battlefield rather than following player behind camp");
  var cameraRoot=scene.CreateGameObject("Camera clearance test");cameraRoot.Transform.WorldPosition=new(0,1.7f,5);var camera=cameraRoot.AddComponent(new Camera3D());scene.SetActiveCamera(camera);autonomous.Transform.WorldPosition=cameraRoot.Transform.WorldPosition+cameraRoot.Transform.Forward*2;defender.Tick(.001f);Check(!defender.HiddenForCamera,"drone stays visible when crossing the camera sightline; steering handles avoidance");
  autonomous.Transform.WorldPosition+=cameraRoot.Transform.Right*12;defender.Tick(.001f);Check(!defender.HiddenForCamera,"drone becomes visible again after clearing the camera sightline");
  // Independent loads reserve actual cargo and cannot sell/duplicate the same raw ore.
  Set(op,"Phase",MiningPhase.Preparation);Set(op,"RawOre",120);Set(op,"RefinedOre",0);op.QueueRefineryBatches=true;op.RefineryBatch=3;
  var extra1=scene.CreateGameObject("Extra refinery one").AddComponent(new MiningAuxiliaryRefinery3D{OperationObjectId=owner.Id});var extra2=scene.CreateGameObject("Extra refinery two").AddComponent(new MiningAuxiliaryRefinery3D{OperationObjectId=owner.Id});
  Check(extra1.BeginLoad()&&extra2.BeginLoad()&&extra1.LoadedRaw==50&&extra2.LoadedRaw==50&&op.RawOre==20&&op.CargoUsed==120,"two independent 50-ore loads reserve cargo without losing hold usage");
  Check(op.BeginRefining()&&!op.SellUnits(false,21,1),"reserved ore cannot also be sold through market");for(int i=0;i<18;i++){extra1.Tick(3.01f);extra2.Tick(3.01f);op.Tick(3.01f);}Check(op.RawOre==0&&op.RefinedOre==120&&extra1.LoadedRaw==0&&extra2.LoadedRaw==0,"parallel refineries and original refinery conserve all ore");
  int originalBatch=op.RefineryLevel;Check(extra1.BuyUpgrade(0)&&extra1.BatchLevel==1&&extra2.BatchLevel==0&&op.RefineryLevel==originalBatch,"upgrading one extra refinery never upgrades another refinery or the original");Set(op,"RawOre",80);extra1.LoadCapacity=10;extra2.LoadCapacity=30;Check(extra1.BeginLoad()&&extra2.BeginLoad()&&extra1.LoadedRaw==10&&extra2.LoadedRaw==30,"each refinery enforces its own configured load limit");extra1.Tick(1);Check(extra1.Remaining<extra2.Remaining,"each refinery advances its own processing clock");
  int oreBefore=op.RefinedOre,creditsBefore=op.Credits;op.AddTestingRefinedOre(100);Check(op.RefinedOre==oreBefore+100&&op.Credits==creditsBefore,"refined-ore cheat adds only the requested testing resource");
  var market=owner.AddComponent(new MiningTrade3D{OperationObjectId=owner.Id,PersistProgress=false});market.Initialize();Check(Math.Abs(market.Quote(true)-op.RefinedOrePrice*1.2f)<.01f,"live exchange quotes include the 20 percent uplift");
  var flightScene=new Scene("Flying navigation");var flyPlayer=flightScene.CreateGameObject("Player");flyPlayer.Transform.WorldPosition=new(30,0,0);var flyRig=flightScene.CreateGameObject("Rig");var flyOwner=flightScene.CreateGameObject("Operation");var flyOp=flyOwner.AddComponent(new MiningOperation3D{PlayerObjectId=flyPlayer.Id,DrillObjectId=flyRig.Id,PersistProgress=false,TutorialEnabled=false,TargetEnabled=false});flyOp.Initialize();
  var obstacle=flightScene.CreateGameObject("Wide refinery collision");obstacle.Transform.WorldPosition=new(0,2.5f,0);obstacle.AddComponent(new BoxCollider3D{Size=new(12,5,3)});var flyer=flightScene.CreateGameObject("Pathfinding drone");flyer.Transform.WorldPosition=new(0,1.7f,8);var navigator=flyer.AddComponent(new MiningSecurityDrone3D{OperationObjectId=flyOwner.Id});var move=typeof(MiningSecurityDrone3D).GetMethod("MoveTo",BindingFlags.NonPublic|BindingFlags.Instance)!;
  for(int i=0;i<200;i++)move.Invoke(navigator,[new Vector3(0,1.7f,-12),.1f]);Check(Vector3.Distance(flyer.Transform.WorldPosition,new(0,1.7f,-12))<1,"3D flight route passes around or above a refinery instead of sticking against it");
  var flyEnemies=(List<GameObject>)typeof(MiningOperation3D).GetField("_enemies",BindingFlags.NonPublic|BindingFlags.Instance)!.GetValue(flyOp)!;var diveVictim=flightScene.CreateGameObject("Nearest dive victim");diveVictim.Transform.WorldPosition=flyer.Transform.WorldPosition+new Vector3(4,-1,0);diveVictim.AddComponent(new HealthComponent());flyEnemies.Add(diveVictim);Set(flyOp,"Phase",MiningPhase.Drilling);var feel=flyOwner.AddComponent(new MiningGameFeel3D());navigator.RestoreBattery(6);navigator.Tick(.1f);Check(navigator.TacticalState=="Final dive"&&navigator.CurrentTargetObjectId==diveVictim.Id,"10 percent battery selects nearest enemy for final dive");for(int i=0;i<20&&!navigator.Detonated;i++)navigator.Tick(.1f);Check(navigator.Detonated,"final dive detonates on arrival rather than waiting for zero battery");Check(feel.DefenceLossMessage.Contains("SECURITY DRONE DESTROYED"),"drone destruction produces a visible player notification");
  VerifyBarricadeBreach();

 }
 static void VerifyBarricadeBreach(){var s=new Scene("Barricade route tests");var player=s.CreateGameObject("Player");player.Transform.WorldPosition=new(0,0,-12);var owner=s.CreateGameObject("Research");var shop=owner.AddComponent(new MiningResearchStation3D());var barriers=(List<GameObject>)typeof(MiningResearchStation3D).GetField("barricades",BindingFlags.NonPublic|BindingFlags.Instance)!.GetValue(shop)!;var barrier=s.CreateGameObject("Blocking cover");barrier.Transform.WorldPosition=new(0,0,-4);barrier.AddComponent(new BoxCollider3D{Center=new(0,.5f,0),Size=new(3,1,.4f)});var health=barrier.AddComponent(new HealthComponent{MaxHealth=180,CurrentHealth=180});barriers.Add(barrier);var hunter=s.CreateGameObject("Hunter");var brain=hunter.AddComponent(new ByteEngine.Core.AI.AIBehavior3D{TargetObjectId=player.Id});var combat=hunter.AddComponent(new SimpleEnemyAI3D{TargetId=player.Id});var breaker=hunter.AddComponent(new MiningBarricadeBreaker3D{NormalTargetId=player.Id});breaker.Tick(.3f);Check(breaker.BlockingBarricadeId==barrier.Id&&brain.TargetObjectId!=player.Id,"player hunter prioritizes a barricade obstructing its approach");var contact=s.FindGameObject(brain.TargetObjectId)!;contact.GetComponent<HealthComponent>()!.Damage(10);Check(health.CurrentHealth==180,"spider cannot damage cover remotely");hunter.Transform.WorldPosition=new(0,0,-2.7f);breaker.Tick(.3f);contact.GetComponent<HealthComponent>()!.Damage(10);Check(health.CurrentHealth==170,"spider attacks barricade only within surface melee reach");s.DestroyGameObject(barrier);breaker.Tick(.3f);Check(brain.TargetObjectId==player.Id&&breaker.BlockingBarricadeId==Guid.Empty,"hunter resumes player pursuit after barricade breaks");}

}
